import random

class Solution:
    def __init__(self, m: int, n: int):
        self.m, self.n = m, n
        self.used = set()

    def flip(self) -> List[int]:
        while True:
            idx = random.randrange(self.m * self.n)
            if idx not in self.used:
                self.used.add(idx)
                return [idx // self.n, idx % self.n]

    def reset(self) -> None:
        self.used.clear()

