class Solution {
    int m, n;
    unordered_set<int> used;
public:
    Solution(int m, int n) : m(m), n(n) {}

    vector<int> flip() {
        while (true) {
            int idx = rand() % (m * n);
            if (!used.count(idx)) {
                used.insert(idx);
                return {idx / n, idx % n};
            }
        }
    }

    void reset() { used.clear(); }
};

