import random

class Solution:
    def __init__(self, m: int, n: int):
        self.m, self.n = m, n
        self.total = m * n
        self.swap = {}

    def flip(self) -> List[int]:
        r = random.randrange(self.total)
        val = self.swap.get(r, r)
        self.total -= 1
        self.swap[r] = self.swap.get(self.total, self.total)
        return divmod(val, self.n)

    def reset(self) -> None:
        self.total = self.m * self.n
        self.swap.clear()

