class Solution {
    int m, n, total;
    unordered_map<int, int> swap_;
public:
    Solution(int m, int n) : m(m), n(n), total(m * n) {}

    vector<int> flip() {
        int r = rand() % total--;
        int val = swap_.count(r) ? swap_[r] : r;
        swap_[r] = swap_.count(total) ? swap_[total] : total;
        return {val / n, val % n};
    }

    void reset() { total = m * n; swap_.clear(); }
};

