class Solution {
    private int m, n, total;
    private Map<Integer, Integer> swap = new HashMap<>();
    private Random rand = new Random();

    public Solution(int m, int n) { this.m = m; this.n = n; this.total = m * n; }

    public int[] flip() {
        int r = rand.nextInt(total--);
        int val = swap.getOrDefault(r, r);
        swap.put(r, swap.getOrDefault(total, total));
        return new int[]{val / n, val % n};
    }

    public void reset() { total = m * n; swap.clear(); }
}

